WITH payload AS (SELECT $archive_payload$[{"id":"d76a6db8-2080-591b-b185-9620e08d2f38","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط -تفحيط للمرة الثالثة -إنكار للدعوى -شاهد واحد على دعوى -تعزير للتهمة -تعزير بالسجن واجللد وحجز السيارة - سحب رخصة القيادة ملدة سنة ومنعه من القيادة أثناءها.","document_number":"34272957","case_number":"34169778","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة تبوك على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/18","year":"1434","subject":"تفحيط -تفحيط للمرة الثالثة -إنكار للدعوى -شاهد واحد على دعوى -تعزير للتهمة -تعزير بالسجن واجللد وحجز السيارة - سحب رخصة القيادة ملدة سنة ومنعه من القيادة أثناءها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 34272957:‬تاريخه‪1434/07/18 :‬هـ‬\n                     ‫رقم الدعوى‪34169778:‬‬\n               ‫رقم قرار التصديق من محكمة‬\n    ‫االستئناف‪ 34316475:‬تاريخه‪1434/09/01:‬ه‬\n\n\n\n‫تفحيــط‪ -‬تفحيــط للمــرة الثالثــة ‪ -‬إنــكار للدعــوى‪ -‬شــاهد واحــد علــى‬\n‫دعــوى‪ -‬تعزيــر للتهمــة ‪ -‬تعزيــر بالســجن واجللــد وحجــز الســيارة ‪-‬‬\n         ‫ســحب رخصــة القيــادة ملــدة ســنة ومنعــه مــن القيــادة أثناءهــا‪.‬‬\n\n\n\n\n‫‪-‬مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف‬\n                                                        ‫تســبيب حكمــه‪.‬‬\n\n\n\n\n‫مت توجيــه االتهــام للمدعــى عليــه بقيامــه بالتفحيط للمــرة الثالثة‪ ،‬وذلك‬\n‫بعــد مشــاهدته يقــوم مبمارســة «التفحيــط»‪ ،‬وتبــن أنــه يوجــد عليــه‬\n‫مخالفتــي تفحيــط ‪ -‬طلــب املدعــي العــام احلكــم علــي املدعــى عليــه‬\n‫بالســجن والغرامــة املاليــة ومصــادرة املركبــة اســتناد ًا للفقــرة (ج) مــن‬\n‫املــادة (‪ )69‬مــن نظــام املــرور ‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى‬\n‫عليــه‪ ،‬صــادق علــى ملكيتــه الســيارة‪ ،‬وعلــى مخالفتــي التفحيــط‪،‬‬\n‫وأنكــر قيامــه بالتفحيــط للمــرة الثالثــة‪ -‬مت ســماع شــهادة الشــاهد‪،‬‬\n‫وتزكيتــه‪ -‬لــم تثبــت إدانــة املدعــى عليــه مبــا نســب إليــه ومت احلكــم‬\n‫بــرد طلــب املدعــي العــام تطبيــق الفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام‬\n‫املــرور لعــدم ثبــوت مــا يدعيــه ونظــر ًا إلــى مــا جــاء يف إقــرار املدعــى عليــه‬\n\n                                                                                            ‫‪40‬‬\n\f     ‫بالقبــض عليــه يف قضيتــي تفحيــط وإلقــراره كذلــك بوجــوده باملــكان‬\n     ‫الــذي ميــارس فيــه التفحيــط وملــا جــاء يف شــهادة الشــاهد املعــدل شــرع ًا‬\n     ‫ممــا يوجــه التهمــة يف حــق املدعــى عليــه مت احلكــم لقــاء ذلــك بجلــده‬\n     ‫أربعــن جلــدة وســجنه ثالثــن يوم ـ ًا وســحب رخصــة املدعــى عليــه ملــدة‬\n     ‫ســنة ومنعــه مــن قيــادة الســيارة خــال هــذه املــدة وحجــز ســيارته مــدة‬\n     ‫خمســة أشــهر ‪ -‬بعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n     ‫املدعــى عليــه قناعتــه بــه وقــرر املدعــي العــام عــدم القناعــة‪ -‬وبعــد رفــع‬\n                             ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بتبوك‪/‬املكلــف برقــم ‪ 34169778‬وتاريــخ ‪ 1434/04/14‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 34905845‬وتاريــخ ‪ 1434/04/14‬ه ـ ففــي‬\n     ‫يــوم الثالثــاء املوافــق‪ 1434/05/07‬ه ـ حضــر املدعــي العــام ‪ ...‬ســعودي‬\n     ‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ..‬مــن مرجعــه مبوجــب اخلطــاب رقــم‬\n     ‫‪ 13058‬يف ‪1433/9/5‬ه ـ وحضــر حلضــوره …‪ ..‬والبالــغ مــن العمــر(‪)24‬‬\n     ‫عام ـ ًا ســعودي اجلنســية يحمــل ســجل مدنــي رقــم(‪ ).....‬وبالرجــوع‬\n     ‫للمعاملــة وجدتهــا مشــتملة علــى الئحــة دعــوى عامــة ضــد املذكــور‬\n     ‫ـاء‬\n      ‫وفيهــا أنــه بتاريــخ ‪1433/12/06‬ه ـ الســاعة العاشــرة والنصــف مسـ ً‬\n     ‫تقريبـ ًا الحــظ أحــد أفــراد دوريــات البحــث والتحــري ســيارة …… رقــم‬\n     ‫اللوحــة(‪ )… ..‬يقــوم قائدهــا باالســتعراض بســيارته (التفحيــط) بطريــق‬\n     ‫‪ ...........‬ومت إبــاغ العمليــات واجتهــت دوريــة رســمية مــن املــرور للموقــع‬\n‫‪41‬‬\n\f‫ومت اســتيقاف الســيارة املشــار إليهــا وضبطهــا بقيــادة املدعــى عليــه‬\n‫وعنــد الرجــوع لســجل مخالفاتــه تبــن أنــه يوجــد عليــه مخالفتــي تفحيــط‬\n‫األولــى بتاريــخ ‪1433/05/24‬ه ـ والثانيــة بتاريــخ ‪1433/11/24‬ه ـ‬\n‫وصــدر بحقــه قــرار هيئــة الفصــل يف املنازعــات واملخالفــات املروريــة‬\n‫رقــم (‪ )1066‬وتاريــخ ‪1433/12/6‬ه ـ وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام للمدعــى عليــه …‪ ..‬بقيامــه باالســتعراض بســيارته (التفحيــط)‬\n‫للمــرة الثالثــة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل مجــرم وعاقــب‬\n‫عليــه نظام ـ ًا اســتناد ًا للمــادة(‪ )69‬مــن نظــام املــرور الصــادر باملرســوم‬\n‫امللكــي رقــم(م‪ )85/‬وتاريــخ ‪1428/11/26‬ه ـ لــذا أطلــب ‪ -1‬إثبــات‬\n‫مــا أســند إليــه‪ -2 .‬احلكــم عليــه بالســجن والغرامــة املاليــة ومصــادرة‬\n‫املركبــة اســتناد ًا للفقــرة (ج) مــن املــادة (‪ )69‬مــن النظــام املشــار إليــه‬\n‫أعــاه‪ .‬هكــذا ادعــى وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام مــن أن الســيارة …… املذكــورة يف الدعــوى‬\n‫عائــدة لــي وأنــا مــن يقودهــا فصحيــح وقــد مت القبــض علــي يف قضيــة‬\n‫تفحيــط مرتــن ومتــت مجازاتــي علــى ذلــك وأمــا مــا ذكــره املدعــي‬\n‫العــام مــن قيامــي بالتفحيــط يف املــرة الثالثــة علــى طريــق املطــار القــدمي‬\n‫فغيــر صحيــح والصحيــح أننــي كنــت جالس ـ ًا علــى املــزروع وكانــت‬\n‫ســيارتي واقفــة علــى الطريــق وكان هنــاك ثــاث ســيارات مــن نــوع‪....‬‬\n‫يقــوم أصحابهــا بالتفحيــط هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n‫العــام قــال الصحيــح مــا جــاء يف دعــواي وبســؤال املدعــي العــام عــن بينتــه‬\n‫قــال أطلــب مهلــة إلحضــار معــدي محضــر املشــاهدة والقبــض ورفعــت‬\n‫اجللســة لذلــك ويف يــوم األربعــاء املوافــق‪ 1434/05/22‬ه ـ حضــر املدعي‬\n‫العــام ولــم يحضــر املدعــى عليــه وبطلــب البينــة مــن املدعــي العــام أحضــر‬\n\n\n                                                                                      ‫‪42‬‬\n\f     ‫للشــهادة وأدائهــا …‪ .‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم …‪..‬‬\n     ‫وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي رأيــت ســيارة مــن‬\n     ‫نــوع ‪ ....‬علــى طريــق ‪ ..........‬ميــارس قائدهــا التفحيــط وقــد قــام صاحــب‬\n     ‫الســيارة بتغطيــة احلــرف األول مــن اجلهــة اليمنــى وقــد رأيتــه يقــوم‬\n     ‫بالتفحيــط ثــاث مــرات يف نفــس املــكان وكان ذلــك حوالــي الســاعة‬\n     ‫ـاء ثــم قمــت بإبــاغ دوريــات املــرور ومت القبــض عليــه‬      ‫احلاديــة عشــرة مسـ ً‬\n     ‫هــذا مــا لــدي هكــذا شــهد وبطلــب تزكيــة الشــاهد حضــر كال مــن‬\n     ‫…‪ .‬و … املــدون هويتهمــا يف ضبطــه وشــهد كل واحــد منهمــا بقولــه‬\n     ‫أشــهد هلل بــأن الشــاهد عــدل ثقــة وال نعلــم عنــه إال خيــر ًا هكــذا شــهدا‬\n     ‫وعليــه رفعــت اجللســة إلبــاغ املدعــى عليــه وعــرض مــا جــاء يف شــهادة‬\n     ‫الشــاهد عليــه ويف يــوم الثالثــاء املوافــق‪ 1434/07/18‬ه ـ حضر املدعي‬\n     ‫العــام واملدعــى عليــه وبعــرض الشــاهد ومــا جــاء يف شــهادته علــى املدعــى‬\n     ‫عليــه أجــاب بقولــه مــا جــاء يف شــهادة الشــاهد مــن أننــي أمتلــك ســيارة‬\n     ‫‪ ......‬وأننــي كنــت موجــود علــى طريــق املطــار القــدمي وقــت التفحيــط‬\n     ‫كلــه صحيــح ومــا ذكــره مــن قيامــي بالتفحيط وتغطيتــي للحرف األول‬\n     ‫فقــط مــن اللوحــة غيــر صحيــح والصحيــح أننــي كنــت واقفـ ًا بجــوار ‪...‬‬\n     ‫وقــد قمــت بتغطيــة احلــرف األول والرقــم األول هكــذا أجــاب فنظــر ًا‬\n     ‫إلــى مــا دون مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بالقبــض عليــه‬\n     ‫يف قضيتــي تفحيــط وإلقــراره كذلــك بوجــوده باملــكان الــذي ميــارس يف‬\n     ‫التفحيــط وهــو طريــق املطــار القــدمي وملــا جــاء يف شــهادة الشــاهد املعــدل‬\n     ‫شــرع ًا وبنــاء ًا علــى جميــع مــا تقــدم لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا‬\n     ‫نســب إليــه وإمنــا تتوجــه لــه التهمــة بذلــك وقــررت تعزيــره مبــا يلــي أو ًال‬\n     ‫جلــد املدعــى عليــه أربعــن جلــد دفعــة واحــدة ثانيـ ًا حبــس املدعــى عليــه‬\n\n\n‫‪43‬‬\n\f‫ملــدة ثالثــن يوم ـ ًا يحتســب منهــا فتــرة إيقافــه علــى ذمــة القضيــة ثالث ـ ًا‬\n‫ســحب رخصــة املدعــى عليــه ملــدة ســنه ومنعــه مــن قيــادة الســيارة خــال‬\n‫هــذه املــدة رابعـ ًا حجــز ســيارة املدعــى عليــه ملــدة خمســة أشــهر اعتبــار ًا‬\n‫مــن تاريــخ إيداعهــا احلجــز خامسـ ًا رد طلــب املدعــي العــام تطبيــق الفقــرة‬\n‫(ج) مــن املــادة (‪ )69‬مــن نظــام املــرور لعــدم ثبــوت مــا يدعيــه ومبــا ذكــر‬\n‫حكمــت وبعــرض ذلــك علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى‬\n‫عليــه قناعتــه بــه وأمــا املدعــي العــام فقــرر عــدم قناعتــه بــه مســبب ًا ذلــك‬\n‫مبطالبتــه مبصــادرة الســيارة وتغــرمي املدعــى عليــه وطلــب متييــز احلكــم‬\n‫فأجبتــه لطلبــه وســيتم بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/18‬ه ـ احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪34905845‬‬\n‫وتاريــخ ‪1434/7/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫‪ .....‬برقــم ‪ 34272957‬وتاريــخ ‪1434 /7/18‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد‪ .... /‬ســعودي اجلنســية يف قضيــة تفحيــط علــى النحــو املوضــح‬\n‫يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ‪ .‬قررنــا املصادقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                ‫وســلم‬\n\n\n\n\n                                                                                          ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":40,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c3315e8913d996c08460c347161c5952cf5a1203b4f741cb2e18163f11b7616b","normalized_text_hash":"69c21a11f48c3102c7444d6ae487f9ab55b639ece64565ab2449e97e99859756","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p40-34272957"},{"id":"1abf194a-f6fa-5143-ba25-ceabd29c9f12","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط -تفحيط أدى إلى دهس ووفاة -انتهاء احلق اخلاص - انكار املدعى عليه -عدم البينة املوصلة -رد دعوى لعدم ثبوتها .- -قوله صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على","document_number":"34215918","case_number":"34204737","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/04","year":"1434","subject":"تفحيط -تفحيط أدى إلى دهس ووفاة -انتهاء احلق اخلاص - انكار املدعى عليه -عدم البينة املوصلة -رد دعوى لعدم ثبوتها .- -قوله صلى اهلل عليه وسلم ( :البينة على املدعي واليمن على","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34215918:‬تاريخه‪1434/05/04 :‬هـ‬\n                          ‫رقم الدعوى‪34204737:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34236886:‬تاريخه‪1434/06/11:‬هـ‬\n\n\n\n     ‫تفحيــط ‪ -‬تفحيــط أدى إلــى دهــس ووفــاة ‪ -‬انتهــاء احلــق اخلــاص ‪-‬‬\n     ‫انــكار املدعــى عليــه ‪ -‬عــدم البينــة املوصلــة ‪ -‬رد دعــوى لعــدم ثبوتهــا ‪.-‬‬\n\n\n\n\n     ‫‪-‬قولــه صلــى اهلل عليــه وســلم ‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                         ‫املدعــى عليــه)‬\n           ‫‪-‬األصل براءة الذمة وال ينتقل عنها إال بدليل صريح صحيح‪.‬‬\n     ‫‪-‬الفقــرة احلاديــة واألربعــن مــن املــادة الثانيــة مــن نظــام املــرور والئحته‬\n                                                                              ‫التنفيذية‪.‬‬\n\n\n\n\n     ‫انتهــى التحقيــق بتوجيــه االتهــام للمدعــى عليــه بالتفحيــط ممــا نتــج‬\n     ‫عنــه وفــاة شــخص ومســئوليته عــن احلــادث بنســبة (‪ )%100‬وذلــك بعــد‬\n     ‫ـخص مــن‬‫ورود بــاغ للجهــات املختصــة مفــاده وقــوع حــادث دهــس لشـ ٍ‬\n     ‫قبــل ســيارة بقيــادة املدعــى عليــه وجنــم عــن احلــادث وفــاة املدهــوس ‪-‬‬\n     ‫طلــب املدعــي العــام احلكــم عليــه بعقوبــة تعزيريــة وفق ـ ًا للفقــرة الثانيــة‬\n     ‫مــن الالئحــة التنفيذيــة يف املــادة رقــم (‪ )62‬مــن نظــام املــرور‪ -‬بعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أنكــر التفحيــط وقــرر أنــه قــام‬\n     ‫بالضغــط علــى البنزيــن كونــه مســتعجال‪ ،‬فأســرعت الســيارة ممــا‬\n‫‪45‬‬\n\f‫نتــج عنــه انحرافهــا وحصــول احلــادث وطلــب رد دعــوى املدعــي العــام‪-‬‬\n‫لــم يقــم املدعــي العــام البينــة املوصلــة علــى دعــواه‪ -‬نظــر ًا ألن املدعــي‬\n‫العــام ال بينــة لــه علــى دعــواه واألصــل بــراءة الذمــة وكــون املدعــى‬\n‫عليــه صغيــر الســن ممــا يــدل علــى عــدم قدرتــه يف التصــرف بالســيارة‬\n‫أثنــاء الســرعة ومــا جــاء يف الفقــرة احلاديــة واألربعــن مــن املــادة الثانيــة‬\n‫مــن نظــام املــرور والئحتــه التنفيذيــة مــن تفســير معنــى التفحيــط‪ ،‬مت‬\n‫احلكــم بــرد دعــوى املدعــي العــام وإخــاء ســبيل املدعــى عليــه‪ -‬بعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام‬\n‫عدمهــا وطلــب رفــع احلكــم حملكمــة االســتئناف دون الئحــة ‪ -‬بعــد رفــع‬\n                         ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/5/12‬ه ـ لــدي أنــا ‪....‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف افتتحــت اجللســة يف‬\n‫الســاعة التاســعة والنصــف بنــاء ًا علــى املعاملــة احملالــة لنا مــن رئيس هذه‬\n‫احملكمــة برقــم ‪ 34204737‬يف ‪1434/5/4‬ه ـ واملقيــدة لــدى احملكمة‬\n‫بالقيــد رقــم ‪ 341091618‬يف ‪1434/5/4‬ه ـ ويف هــذه اجللســة حضــر‬\n‫ا بصفتــي مدعي ـ ًا عامــا يف دائــرة التحقيــق‬    ‫املدعــي العــام ‪ ...‬وقــرر قائ ـ ً‬\n‫واالدعــاء العــام مبحافظــة القطيــف أدعــي علــى ‪ ... :‬ســعودي اجلنســية‬\n‫مبوجــب الهويــة الوطنيــة رقــم (‪ ).....‬تبلــغ مــرور محافظــة القطيــف عــن‬\n‫وقــوع حــادث دهــس لشــخص وذلــك بحــي ‪ .........‬أمــام مدرســة مــن‬\n‫قبــل ســيارة مــن نــوع (‪ )........‬حتمــل اللوحــة رقــم (‪ )... .‬بقيــاد املدعــى‬\n‫عليــه وقــد جنــم عــن احلــادث وفــاة ‪ .... /‬وصــدر بحقــه شــهادة وفــاة مــن‬\n\n                                                                                         ‫‪46‬‬\n\f     ‫إدارة األحــوال املدنيــة بالدمــام رقــم (‪ )....‬وتاريــخ ‪1433/4/20‬ه ـ ومــن‬\n     ‫خــال محضــر املعاينــة والرســم التخطيطــي للحــادث وســماع أقــوال‬\n     ‫املدعــى عليــه وشــهادة الشــهود تبــن أن املدعــى عليــه كان يســير‬\n     ‫بســيارته املذكــورة أعــاه قادم ـ ًا مــن الشــرق باجتــاه الغــرب ممارس ـ ًا‬\n     ‫لعمليــة التفحيــط ففقــد الســيطرة علــى الســيارة ممــا أدى إلــى صدمــه‬\n     ‫شــخص بالركــن األمامــي األيســر للســيارة ومــن ثــم اســتقرت الســيارة‬\n     ‫بعمــود إنــارة مبقدمتهــا (جــرى فــرز أوراق مســتقلة للحــادث) وقــد انتهــى‬\n     ‫التحقيــق معــه عــن توجيــه االتهــام إليــه بالتفحيــط ممــا نتــج عنــه وفــاة‬\n     ‫شــخص اثــر مســئوليته عــن احلــادث بنســبة (‪ )%100‬حيــث إن مــا أقــدم‬\n     ‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبرة شــرع ًا فعل محــرم ومعاقب‬\n     ‫عليــه شــرع ًا لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة‬\n     ‫تعزيريــة رادعــة لقــاء تســببه يف إهــاك األبريــاء وإتــاف املمتلــكات‬\n     ‫وفق ـ ًا للفقــرة الثانيــة مــن الالئحــة التنفيذيــة يف املــادة رقــم (‪ )62‬مــن‬\n     ‫نظــام املــرور ووفقـ ًا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )65358‬وتاريــخ‬\n     ‫‪1432/6/25‬ه ـ (علمــا أن احلــق اخلــاص انتهــى ) هــذه دعــواي وبــاهلل‬\n     ‫التوفيــق هــذا وقــد حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫ا مــا ذكــره‬ ‫رقــم ‪ ....‬وبســؤاله عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n     ‫املدعــي العــام يف دعــواه مــن أننــي قمــت بالتفحيــط قبــل احلــادث فغيــر‬\n     ‫صحيــح بــل الصحيــح هــو أننــي قمــت بالضغــط علــى البنزيــن فأســرعت‬\n     ‫ممــا نتــج عنــه انحــراف الســيارة منــي وزاحــت فحصــل احلــادث املذكــور‬\n     ‫يف الدعــوى وأطلــب رد دعــوى املدعــي هــذا جوابــي هــذا وبســؤال املدعــي‬\n     ‫العــام هــل لديــه بينــة علــى مــا جــاء يف دعــواه فقــال نعــم وأحضــر معــه‬\n     ‫‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وطلــب ســماع مــا‬\n\n\n‫‪47‬‬\n\f‫لديــه مــن شــهادة وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل تعالــى‬\n‫بأننــي كنــت وقــت احلــادث الــوارد يف الدعــوى موجــود ًا يف املوقــع ورأيــت‬\n‫ســيارة املدعــى عليــه تضــرب املجنــي عليــه وألقتــه علــى األرض والدمــاء‬\n‫تخــرج مــن رأســه وتــويف يف احلــال هــذا مــا شــاهدته ولــم أشــاهد املدعــى‬\n‫عليــه يقــوم بعمليــه التفحيــط هــذا مــا لــدي مــن شــهادة هكــذا شــهد ثــم‬\n‫جــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينــة فقــال نعــم وأطلــب املهلــة‬\n‫إلحضارهــا هكــذا قــرر لــذا رفعــت اجللســة ملــا طلبــه املدعــي العــام ومت‬\n‫تأجيلهــا ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه املذكــور‬\n‫ســابق ًا هــذا وبســؤال املدعــي العــام هــل أحضر البينة التــي وعد بها فقال‬\n‫بينتــي مــا ورد يف أوراق املعاملــة هكــذا أجــاب ثــم جــرى منــي االطــاع‬\n‫علــى أوراق املعاملــة فلــم أجــد فيهــا مــا يديــن املدعــى عليــه ا‪.‬ه ـ ثــم جــرى‬\n‫ســؤال املدعــى عليــه عــن قصــده يف الضغــط علــى البنزيــن ومــا أســباب‬\n‫ال‬‫ا لــم يكــن قصــدي أي شــيء بــل كنــت مســتعج ً‬              ‫ذلــك فأجــاب قائ ـ ً‬\n‫فأســرعت حتــى انحرفــت الســيارة بــي هكــذا أجــاب فبنــاء ًا علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث أنكــر املدعــى‬\n‫عليــه دعــوى املدعــي العــام يف قضيــة التفحيــط وال بينــة للمدعــي العــام‬\n‫علــى دعــواه ســوى مــا ورد يف أوراق املعاملــة والشــاهد الــذي أحضــره إال‬\n‫أن هــذه الشــهادة غيــر موصلــة ومبــا أن األصــل بــراءة الذمــة وال ينتقــل‬\n‫عنهــا إال بدليــل صريــح صحيــح واســتناد ًا حلديــث (البينــة علــى املدعــي‬\n‫واليمــن علــى املدعــى عليــه) ومبــا أن املدعــى عليــه صغيــر بالســن ممــا‬\n‫يــدل علــى عــدم قدرتــه يف التصــرف بالســيارة أثنــاء الســرعة واســتناد ًا‬\n‫للفقــرة احلاديــة واألربعــن مــن املــادة الثانيــة مــن نظــام املــرور والئحتــه‬\n‫التنفيذيــة التــي فســرت معنــى التفحيــط جلميــع ذلــك فقــد حكمــت بــرد‬\n\n\n                                                                                         ‫‪48‬‬\n\f     ‫دعــوى املدعــي العــام وأخليــت ســبيل املدعــى عليــه وبإعــان احلكــم على‬\n     ‫الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم أمــا املدعــي العــام فقــرر‬\n     ‫عــدم القناعــة وطالــب بالتمييــز ورفــع احلكــم إلــى محكمــة االســتئناف‬\n     ‫بــدون الئحــة اعتراضيــة فأجبتــه لذلــك وأمــرت بإخــراج قــرار بذلــك ثــم‬\n     ‫رفــع احلكــم إلــى محكمــة االســتئناف وصلــى اهلل وســلم علــى نبينــا‬\n     ‫محمــد وحــرر يف ‪1434/5/19‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم‬\n     ‫األربعــاء ‪1434/6/21‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة والربــع‬\n     ‫هــذا وقــد وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف باملنطقــة‬\n     ‫الشــرقية مبوجــب اخلطــاب رقــم ‪ 341354333‬وتاريــخ ‪1434/6/18‬ه ـ‬\n     ‫وقــد ظهــر علــى القــرار مبــا نصــه‪( :‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا‬\n     ‫علــى هــذا القــرار رقــم ‪ 34215918‬وتاريــخ ‪1434/5/18‬ه ـ الصــادر‬\n     ‫مــن فضيلــة القاضــي ‪ ....‬وأصدرنــا القــرار رقــم ‪ 34236886‬وتاريــخ‬\n     ‫‪1434/6/11‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي اســتئناف ‪....‬‬\n     ‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬‬\n     ‫ختمــه وتوقيعــه ) وللبيــان حــرر يف ‪1434/6/21‬ه ـ واهلل املوفــق وصلــى‬\n                                                      ‫اهلل وســلم علــى نبينــا محمــد‬\n\n\n\n\n‫‪49‬‬\n\f50\n\f51\n\f52\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":45,"source_page_end":52,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"519a3df9c7f288591f2c550fb0186514827063fe201a7a66f25e5071fad60863","normalized_text_hash":"be91fc5aa7686caadc3a01c7f0160bf0628db87abb2134d413b5026d9759923b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p45-34215918"},{"id":"cdcf7ed6-2bda-5e5b-b7ba-5a1f8c5b93d1","document_type":"judgment","category":"judicial","subcategory":"general","title":"تهديد -التهديد بإرسال رسائل نصية عن طريق اجلوال -اإلقرار بالتهديد -التعزير للحق العام واخلاص بالسجن واجللد ،ومتكن املدعي باحلق اخلاص من حضور اجللد املرتبط بحقه.","document_number":"33471937","case_number":"3360241","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف ولم يبد املدعي العام اعتراضا على احلكم جرى النطق باحلكم يف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/4","year":"1434","subject":"تهديد -التهديد بإرسال رسائل نصية عن طريق اجلوال -اإلقرار بالتهديد -التعزير للحق العام واخلاص بالسجن واجللد ،ومتكن املدعي باحلق اخلاص من حضور اجللد املرتبط بحقه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33471937 :‬تاريخه‪1433/12/4 :‬هـ‬\n                           ‫رقم الدعوى‪3360241:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34295815‬تاريخه‪1434/8/14 :‬هـ‬\n\n\n\n     ‫تهديــد‪ -‬التهديــد بإرســال رســائل نصيــة عــن طريــق اجلــوال‪ -‬اإلقــرار‬\n     ‫بالتهديــد‪ -‬التعزيــر للحــق العــام واخلــاص بالســجن واجللــد‪ ،‬ومتكــن‬\n                 ‫املدعــي باحلــق اخلــاص مــن حضــور اجللــد املرتبــط بحقــه‪.‬‬\n\n\n\n                    ‫‪ -‬قول اهلل تعالى‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين)‬\n     ‫‪ -‬قولــه صلــى اهلل عليــه وســلم (املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                            ‫ويــده)‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه بإرســال رســائل تهديــد وتلفــظ للمدعــي‬\n     ‫باحلــق اخلــاص عــن طريــق اجلــوال ‪ -‬بالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n     ‫أي ســوابق جنائيــة ‪ -‬طلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بعقوبــة تعزيريــة ‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n     ‫صــادق عليهــا جملــة وتفصيــا وأنــه فعــل ذلــك بســبب خــاف مالــي علــى‬\n     ‫أجــرة الشــقة التــي اســتأجرها منــه املدعــي باحلــق اخلاص‪ -‬حضــر املدعي‬\n     ‫باحلــق اخلــاص وأضــاف أن املدعــى عليــه يرســل رســائل علــى جوالــه ينعتــه‬\n     ‫فيهــا أنــه ليــس برجــل وأنــه ال خيــر فيــه وطلــب عقابــه بالوجــه الشــرعي‪-‬‬\n     ‫نظــر ًا ألن املدعــى عليــه صــادق علــى قيامــه بإرســال الرســالة مــن جوالــه‬\n     ‫لــذا ثبــت قيــام املدعــى عليــه بإرســال رســائل مــن جوالــه تتضمــن تهديــد‬\n‫‪53‬‬\n\f‫للمدعــي ومت احلكــم عليــه ألجــل احلــق العــام بســجنه خمســة أيــام وجلــده‬\n‫عشــر جلــدات دفعــة واحــدة وألجــل احلــق اخلــاص بســجنه خمســة أيــام‬\n‫وجلــده عشــر جلــدات دفعــة واحــدة وميكــن املدعــي يف احلــق اخلــاص مــن‬\n‫حضــور اجللــد املرتبــط بحقــه ‪ -‬بعــرض احلكــم عليهمــا قــرر املدعــى‬\n‫عليــه واملدعــي باحلــق اخلــاص عــدم القناعــة باحلكــم واســتعدا بتقــدمي‬\n‫الئحــة اعتراضيــة ولــم يبــد املدعــي العــام اعتراضــا علــى احلكــم‪ ،‬وبعــد‬\n                   ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪3360241‬‬\n‫وتاريــخ ‪1433/1/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33155087‬وتاريــخ‬\n‫‪ 1433/01/23‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/11/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي العــام ‪ ......‬وبصفتــي‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام ‪ ) 42 ( ، ......‬عام ـ ًا ‪ ،‬ســعودي‬\n‫اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقــم( ‪ ،) ......‬موقــوف لــدى شــعبة‬\n‫تنفيــذ االحــكام احلقوقيــة شــمال جــدة بنــاء ًا علــى برقيــة صاحــب‬\n‫الســمو امللكــي محافــظ جــدة رقــم‪ ......‬وتاريــخ ‪1432/11/11‬ه ـ علــى‬\n‫ذمــة قضيــة أخــرى ‪.‬حيــث أنــه بتاريــخ ‪1432/12/23‬ه ـ تقــدم املدعــي‬\n‫‪ ، ......‬ســعودي اجلنســية بشــكوى لــدى شــرطة ‪ ......‬بقيــام املدعــى عليــه‬\n‫بتهديــده عــن طريــق ارســال رســالتني نصيتــن االولــى تتضمــن (واهلل‬\n\n                                                                                   ‫‪54‬‬\n\f     ‫ثــم واهلل حاتنــدم وال أنــا مانــي رجــل ‪ ،‬حيجيــك اخليــر يارمة)‪،‬والثانيــة‬\n               ‫تتضمــن (رحــت تشــتك يارمــة‪ ،‬اصــا مــا فيــك خيــر يــا حرمــة) ‪.‬‬\n     ‫وبســماع أقــوال املدعــى عليــه‪ :‬اعتــرف بقيامــه بإرســال هــذه الرســالتني‬\n     ‫للمدعــى وذلــك لكــون املدعــي لــم يــويف باالتفــاق الــذي مت بينهمــا عــن‬\n     ‫طريــق اجلــوال ‪.‬وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n     ‫بإرســال رســائل تهديــد وتلفــظ للمدعــي عــن طريــق اجلــوال‪ .‬وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة ‪-:‬‬\n     ‫‪ /1‬اعترافــه املنــوه عنــه املــدون علــى ص(‪ )12-11‬مــن دفتــر االســتدالل‬\n                                                                        ‫املرفــق لفــة (‪)1‬‬\n     ‫‪ /2‬محضــر االطــاع علــى جــوال املدعــي املــدون علــى ص(‪ )10‬مــن‬\n     ‫دفتــر االســتدالل لفــة رقــم )‪ )1‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n     ‫أي ســوابق جنائيــة وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرع ًا لــذا أطلــب مــن احملكمــة اجلزئيــة مبحافظــة جــدة‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء فعلــه علم ـ ًا‬\n                                                     ‫بــأن احلــق اخلــاص مــازال قائم ـاً‪.‬‬\n     ‫وقــد حضــر املدعــى باحلــق اخلــاص ‪ ......‬ســعودي اجلنســية ســجل مدنــي‬\n     ‫ا‪:‬‬   ‫‪ ......‬وبعــرض دعــوى املدعــى العــام علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫مــا ذكــره املدعــى العــام يف دعــواه صحيــح جملــة وتفصيــا فقــد قمــت‬\n     ‫بإرســال رســالتني علــى جــوال املدعــي بســبب خــاف مالــي بينــي وبينــه‬\n     ‫علــى اجــرة الشــقة التــي اســتأجرها منه هكذا أجــاب ثم اضاف املدعي‬\n     ‫باحلــق اخلــاص إن املدعــى عليــه قــام بإرســال رســائل علــى جوالــي ينعتنــي‬\n     ‫فيهــا بانــي لســت رجــل وإنــي مــا فينــي خيــر واننــي حرمــة واطلــب منكــم‬\n     ‫عقابــه بالوجــه الشــرعي هــذه دعــواه ثــم جــرى منــي رفــع اجللســة للدراســة‬\n\n\n‫‪55‬‬\n\f‫والتأمــل واصــدار احلكــم ويف يــوم االثنــن املوافق‪1433/11/29‬ه ـ ‪-‬‬\n‫افتتحت اجللســة الســاعة العاشــرة وخمســون دقيقة وفيها حضر املدعي‬\n‫العــام واملدعــي يف احلــق اخلــاص واملدعــى عليــه وكانــت اجللســة الســابقة‬\n‫رفعــت للدراســة والتأمــل لــذا قــررت مواصلــة النظــر يف هــذه القضيــة‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث صــادق املدعــى عليــه‬\n‫علــى قيامــه بإرســال الرســالة مــن جوالــه ولقولــه تعالــى (وال تعتــدوا إن‬\n‫اهلل ال يحــب املعتديــن) ولقولــه صلــى اهلل عليــه وســلم (املســلم مــن ســلم‬\n‫املســلمون مــن لســانه ويــده) لذلــك كلــه فقــد ثبــت لــدي قيــام املدعــى‬\n‫عليــه بإرســال رســائل مــن جوالــه تتضمــن تهديــد للمدعــي وحكمــت‬\n‫عليــه ألجــل احلــق العــام بســجنه خمســة ايــام وجلــدة عشــر جلــدات دفعــة‬\n‫واحــدة وحكمــت عليــه ايضــا ألجــل احلــق اخلــاص بســجنه خمســة ايــام‬\n‫وجلــدة عشــر جلــدات دفعــة واحــدة وميكــن املدعــي يف احلــق اخلــاص مــن‬\n‫حضــور اجللــد املرتبــط بحقــه وبعرضــه عليهمــا قــرر املدعــى عليــه عــدم‬\n‫القناعــة باحلكــم وقــرر املدعــي يف احلــق اخلــاص عــدم القناعــة باحلكــم‬\n‫واســتعدا بتقــدمي الئحــة اعتراضيــة وافهمتهمــا ان مــدة تقــدمي االعتــراض‬\n‫هــي ثالثــن يومــا مــن تاريــخ اســتالمهما لصــورة احلكــم وإذا انقضيــت‬\n‫املــدة املذكــورة ولــم يتقدمــا باعتراضهمــا خــال املــدة النظاميــة‬\n‫فســيتم رفــع احلكــم الــى محكمــة االســتئناف ولــم يبــد املدعــي العــام‬\n‫اعتراضــا علــى احلكــم جــرى النطــق باحلكــم يف تاريــخ االثنــن املوافــق‬\n‫‪1433/11/29‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم حــرر يف ‪1433/11/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/1/7‬ه ـ وإثباتـ ًا‬\n‫للواقــع فقــد مضــت مــدة االعتــراض ثالثــون يومــا املقــررة نظامــا وفق ـ ًا‬\n\n\n                                                                                    ‫‪56‬‬\n\f     ‫للمادتــن (‪ )176‬و(‪ )178‬ولــم يقــدم املدعــى عليــه أو مــن ينــوب عنــه‬\n     ‫ـاء‬\n      ‫وال املدعــي باحلــق اخلــاص وال مــن ينــوب عنــه اعتراضهمــا خاللهــا وبنـ ً‬\n     ‫عليــه فقــد ســقط حقهمــا يف طلــب االســتئناف وقــررت رفــع احلكــم‬\n     ‫إلــى محكمــة االســتئناف لتدقيقــه حســب املتبــع وبــاهلل التوفيــق وصلــى‬\n     ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/1/7‬ه ـ احلمــد هلل وحــده‬\n     ‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد جــرى منــا نحــن‬\n     ‫قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف يف منطقة مكة‬\n     ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة مبحافظــة جــدة برقــم (‪ )33155087‬وتاريــخ ‪1434/8/2‬ه ـ‬\n     ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪ ...... /‬القاضي باحملكمة‬\n     ‫اجلزائيــة مبحافظــة جــدة برقــم (‪ )33471937‬وتاريــخ ‪1433/12/4‬ه ـ‬\n     ‫املتضمــن دعــوى املدعــي العــام ضــد‪ ...... /‬ســعودي اجلنســية املتهــم‬\n     ‫بتهديــد شــخص عــن طريــق إرســال رســائل باجلــوال ‪ ،‬احملكــوم فيــه مبــا‬\n     ‫دون بباطــن القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا باألكثرية‬\n     ‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى آل ــه وصحبــه وســلم‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":53,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3836eb2f4d38922c56c1a17a5b4c9e8387ebce777a60460d0b78a3349692195a","normalized_text_hash":"4eaca8ed6f4c1f0be47533a6c959fe26f7d5770e78bf6091e2f01107a8a8ac01","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p53-33471937"},{"id":"7ecff225-dbc9-5cdb-87f2-5f68348b6bb1","document_type":"judgment","category":"judicial","subcategory":"general","title":"تهديد بالقتل -تهديد ناجت عن مالسنة تكثر بن أرباب احلقوق - كون املدعى عليه معلم وكبير يف السن ولم يظهر منه أمارات الطيش واالستخفاف بالدماء ظرف مخفف للعقوبة -االكتفاء بأخذ التعهد على عدم العودة ملثل ما صدر من املدعى عليه - مراعاة نظر الظروف احمليطة واملسببة للقضية.","document_number":"3422002","case_number":"3452991","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/22","year":"1434","subject":"تهديد بالقتل -تهديد ناجت عن مالسنة تكثر بن أرباب احلقوق - كون املدعى عليه معلم وكبير يف السن ولم يظهر منه أمارات الطيش واالستخفاف بالدماء ظرف مخفف للعقوبة -االكتفاء بأخذ التعهد على عدم العودة ملثل ما صدر من املدعى عليه - مراعاة نظر الظروف احمليطة واملسببة للقضية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3422002 :‬تاريخه‪1434/5/22 :‬هـ‬\n                    ‫رقم الدعوى‪3452991:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34247892‬تاريخه‪1434/6/21 :‬هـ‬\n\n\n‫تهديــد بالقتــل‪ -‬تهديــد نــاجت عــن مالســنة تكثــر بــن أربــاب احلقــوق ‪-‬‬\n‫كــون املدعــى عليــه معلــم وكبيــر يف الســن ولــم يظهــر منــه أمــارات‬\n‫الطيــش واالســتخفاف بالدمــاء ظــرف مخفــف للعقوبــة ‪ -‬االكتفــاء‬\n‫بأخــذ التعهــد علــى عــدم العــودة ملثــل مــا صــدر مــن املدعــى عليــه ‪-‬‬\n                    ‫مراعــاة نظــر الظــروف احمليطــة واملســببة للقضيــة‪.‬‬\n\n\n\n\n‫‪ -‬مــا ثبــت يف الصحيحــن أن النبــي صلــى اهلل عليــه وســلم قــال‪ ( :‬إن‬\n                                                   ‫لصاحــب احلــق مقــاالً)‬\n\n\n\n\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بقيامــة بتهديــد‬\n‫أحــد املواطنــن بالقتــل‪ ،‬وذلــك بعدمــا تقــدم أحــد املواطنــن بشــكوى‬\n‫مفادهــا قيــام املدعــى بتهديــده ‪ -‬بالبحــث عــن ســوابق املدعــى عليــه‬\n‫لــم يعثــر لــه علــى ســوابق ‪ -‬طلــب املدعــي العــام إثبــات إدانــة املدعــى‬\n‫عليــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ -‬بعــرض دعــوى‬\n‫املدعــي العــام علــى املدعــى عليــه أنكرهــا‪ ،‬ودفــع أن املدعــي باحلــق‬\n‫اخلــاص كان مســتأجرا حملالتــه الواقعــة علــى الشــارع العــام منــذ عــام‬\n‫‪1424‬ه ـ وانتهــت مــدة اإليجــار ولــم يخــرج فقــال لــه‪( :‬الظاهــر مــا يف حــل‬\n\n                                                                                    ‫‪58‬‬\n\f     ‫إال أنــي أحــط قفــل علــى قفلــك وال تقــدر تفتــح احملــل حتــى يســيل دمــي‬\n     ‫ودمــك يف الشــارع) ‪ ،‬وقــرر أنــه ال يقصــد تهديــده وال ضربــه وإمنــا قصــد‬\n     ‫أنــه لــن يســتطيع فتــح احملــات بعــد ذلــك ‪ -‬جــرى االطــاع علــى إفــادة‬\n     ‫الشــاهد املدونــة علــى أوراق املعاملــة‪ ،‬وبعرضهــا علــى املدعــى عليــه‬\n     ‫أنكرهــا‪ -‬أحضــر املدعــى عليــه شــاهدا ومت ســماع شــهادته ‪ -‬نظــر ًا‬\n     ‫لكــون إجابــة املدعــى عليــه تضمنــت حصــول خــاف بينــه وبــن املواطــن‬\n     ‫املذكــور حــول أجــرة محــات املدعــى عليــه أدى إلــى مشــادة كالميــة‬\n     ‫بينهمــا نتــج عنــه تلفــظ املدعــى عليــه باللفــظ الــوارد يف إجابتــه وهــو‬\n     ‫قولــه (مــا يف حــل إال أنــي أحــط قفــل علــى قفلــك وال تقــدر تفتــح احملــل‬\n     ‫حتــى يســيل دمــي ودمــك يف الشــارع)‪ ،‬وهــذا اللفــظ الصــادر مــن املدعــى‬\n     ‫عليــه موافــق يف املعنــى للفــظ الــوارد يف دعــوى املدعــي العــام حيــث‬\n     ‫تضمــن تهديــد ًا للمذكــور بإقفــال احملــل وعــدم اســتطاعته لفتحــه حتــى‬\n     ‫حتصــل بينهمــا مقاتلــة تســيل علــى إثرهــا الدمــاء وهــذا يــدل علــى شــعور‬\n     ‫املدعــى عليــه بالغــن بســبب مماطلــة املذكــور يف دفــع أجــرة محالتــه‬\n     ‫وألن مــا ورد يف شــهادة املدعــى عليــه يؤيــد أن منشــأ اخلــاف بــن املدعــى‬\n     ‫عليــه واملواطــن املذكــور هــو أجــرة محــات املدعــى عليــه لذلــك كلــه‬\n     ‫ولكــون املدعــى عليــه معلــم وكبيــر يف الســن ولــم يظهــر منــه أمــارات‬\n     ‫الطيــش واالســتخفاف بالدمــاء وإمنــا كان ذلــك منــه يف حلظــة غضــب‬\n     ‫يكثــر حصولــه بــن أربــاب احلقــوق لذلــك كلــه مت احلكــم باالكتفــاء‬\n     ‫بأخــذ التعهــد علــى املدعــى عليــه بعــدم التعــرض للمدعــي للمواطــن‬\n     ‫املذكــور بــأي نــوع مــن األذى يف نفســه أو مالــه أو عرضــه‪ ،‬وإذا كان‬\n     ‫لــه عليــه مطالبــات فيتقــدم بذلــك بشــكوى تأخــذ مجراهــا الشــرعي‬\n     ‫والنظامــي‪ -‬بعــرض ذلــك علــى املدعــى عليــه قــرر قناعتــه باحلكــم وقــرر‬\n\n\n‫‪59‬‬\n\f‫املدعــي العــام عــدم قناعتــه معتبــر ًا الئحــة الدعــوى الئحتــه االعتراضية‪،‬‬\n      ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ......‬القاضــي يف احملكمــة العامــة مبحافظــة قلــوة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫قلــوة برقــم ‪ 3452991‬وتاريــخ ‪ 1434/02/02‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34262843‬وتاريــخ ‪1434/2/2‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام ضــد ‪ ......‬ســعودي بالســجل املدنــي رقــم ‪ ......‬ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1434/03/17‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا‬\n‫حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام مبحافظــة قلــوة‬\n‫‪ ......‬ســعودي بالســجل املدنــي رقــم ‪ ......‬وحضــر حلضــوره املدعــى عليــه‬\n‫وادعــى قائــا بصفتــي مدعيــا عامــا بدائــرة التحقيــق واالدعــاء العــام‬\n‫مبحافظــة قلــوه أدعــي علــى املتهــم فيهــا‪47 ( ...... /‬عام ـ ًا ) ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪( ......‬متزوج‪/‬معلــم) ‪ ،‬لــم يوقــف‬\n‫‪ ،‬ويقيــم مبحافظــة قلــوة إنــه بتاريــخ ‪1433/11/30‬ه ـ تقــدم املواطــن‪/‬‬\n‫‪ ......‬بشــكوى مفادهــا قيــام املدعــى عليــه أعــاه بتهديــده بقولــه ( واهلل‬\n‫ألنثــر دمــك علــى اخلــط وإنــي ألخلــط دمــي بدمــك وإال تطلــع العمــال األن‬\n‫وتدفــع مبلــغ الفــان ريــال )‪.‬وبضبــط إفــادة الشــاهد ‪ ...... /‬أفــاد بأنــه‬\n‫ســمع املدعــى عليــه وهــو يقــول للمدعــي ( تطلــع مــن محالتــي الليلــة وإال‬\n‫يســيل دمــي ودمــك األحســبه ) ‪ .‬باســتجواب املدعــى عليــه ومواجهتــه‬\n‫بالتهمــة املنســوبة إليــه نفــى قيــام بتهديــد املدعــي ‪.‬وقــد انتهــى التحقيــق‬\n\n                                                                                      ‫‪60‬‬\n\f     ‫إلــى توجيــه االتهــام للمدعــى عليــه بقيامــة بتهديــد املواطــن‪ ...... /‬بالقتــل‬\n                                                              ‫وذلــك لألدلــة والقرائــن‪:‬‬\n     ‫‪ -1‬مــا ورد بشــهادة الشــاهد املنــوه عنهــا واملدونــة ص (‪ )9‬مــن دفتــر‬\n                                                             ‫التحقيــق لفــة رقــم (‪. )1‬‬\n           ‫وبالبحث عن سوابقه لم يعثر له على سوابق مسجلة حتى تاريخه‪.‬‬\n     ‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل اهليتــه املعتبــرة‬\n     ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا ‪:‬أطلــب إثبــات إدانتــه مبــا‬\n     ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة زجــر ًا لــه وردع ـ ًا لغيــره‬\n     ‫علمــا أن احلــق اخلــاص مــازال قائمــا وبعــرض ذلــك علــى املدعــى عليــه‬\n     ‫ا مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح جملــة‬         ‫أجــاب قائ ـ ً‬\n     ‫ا والصحيــح أن ‪ ......‬املذكــور كان مســتأجر محالتــي الواقعــة‬            ‫وتفصيـ ً‬\n     ‫علــى الشــارع العــام منــذ عــام ‪1424‬ه ـ ويف شــهر شــعبان عــام ‪1433‬ه ـ‬\n     ‫أخبرتــه أن االيجــارات ارتفعــت فــإذا أراد أن يبقــى يف احملــات ويدفــع‬\n     ‫االجــرة اجلديــدة فلــه ذلــك وإال فيخــرج مــن محالتــي املذكــورة فقــال‬\n     ‫ســأخرج وبــإذن اهلل يف اخــر شــهر شــعبان ومنــذ ذلــك الوقــت حتــى تاريــخ‬\n     ‫‪1433/11/30‬ه ـ وأنــا أراجعــه يف ذلــك ولــم يســتجب لــي يف دفــع االجــرة‬\n     ‫واليف اخلــروج فقلــت لــه الظاهــر مــا يف حــل إال أنــي أحــط قفــل علــى‬\n     ‫قفلــك وال تقــدر تفتــح احملــل حتــى يســيل دمــي ودمــك يف الشــارع ولــم‬\n     ‫أقصــد تهديــده وال ضربــه وانــا قصــدي أنــه لــن يســتطيع فتــح احملــات‬\n     ‫بعــد ذلــك هكــذا قــرر وبعــرض ذلــك علــى املدعــي العــام قــال مــا ذكــره‬\n     ‫املدعــى عليــه غيــر صحيــح والصحيــح مــا ذكرتــه يف دعــواي وبســؤاله‬\n     ‫البينــة علــى مــا جــاء يف دعــواه قــال لــدي بينــة وســأحضرها يف اجللســة‬\n            ‫القادمــة ورفعــت اجللســة الــى يــوم الثالثــاء املوافــق ‪1434/5/7‬ه ـ‬\n\n\n‫‪61‬‬\n\f‫ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي‬\n‫العــام عــن البينــة علــى مــا جــاء يف دعــواه قــال‪ :‬بينتــي مــا يف أوراق املعاملــة‬\n‫وبتصفــح املعاملــة وجــدت علــى الصفحــة التاســعة مــن دفتــر التحقيــق‬\n‫املرفــق لفــة رقــم (‪ )1‬إفــادة الشــاهد املذكــور يف دعــوى املدعــي العــام‬\n‫ونصهــا (( أقــرر أنــا املوقــع أدنــاه بأنــي بعــد صــاة عصــر يــوم ال أذكــره‬\n‫وال التاريــخ قبــل شــهر أو أكثــر كنــت مــع املواطــن ‪ ...... /‬وكنــا نســير‬\n‫مــن الطريــق العــام بالســيارة وعنــد ذلــك حضــر املواطــن ‪ ......‬ومعــه‬\n‫املواطــن ‪ ......‬وحصــل بــن ‪ ......‬و‪ ......‬نقــاش علــى إخــاء منــزل وســمعت‬\n‫املدعــو ‪ ......‬يقــول تطلــع مــن محالتــي الليلــة وإال ســيصل دمــي ودمــك‬\n‫االحســبة هــذا مــا ســمعته وأشــهد بــه ولــم أســمع شــيئ ًا غيــر ذلــك ولــم‬\n‫يقــل ‪ ......‬واهلل ألنثــر دمــك هــذا مــا أشــهد بــه وعليــه أوقــع املقــر مبــا‬\n‫فيــه‪ )) ......‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬مــا ورد يف شــهادة‬\n‫الشــاهد املذكــور غيــر صحيــح ولــدي شــهادة احلاضــر معــي‪ ......‬هكــذا‬\n‫قــرر ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وأحضــر‬\n‫معــه‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ......‬وبســؤاله‬\n‫عــن عمــره وســكنه وصلــة قربتــه باملدعــى عليــه قــال ‪ :‬أبلــغ مــن العمــر‬\n‫خمســة وخمســن عام ًا ومعلم وأســكن يف حي ‪ ......‬يف قلوة وليس بيني‬\n‫وبــن املدعــى عليــه قرابــة واملواطــن ‪ ......‬ابــن عمتــي وبســؤاله عمــا لديــه‬\n‫مــن شــهادة قــال‪ :‬أشــهد أننــي كنــت مــع املدعــى عليــه يف نفــس الوقــت‬\n‫الــذي حصلــت بــه املشــادة بينــه وبــن ‪ ......‬وكان بينهمــا نقــاش حــول‬\n‫إيجــار محــات املدعــى عليــه ثــم قــال املدعــى عليــه ل‪ ......‬راح أحــط قفــل‬\n‫علــى قفــل محلــك وال ينفــك حتــى يســيل دمــي ودمــك يف الشــارع هكــذا‬\n‫شــهد فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث تضمنــت إجابــة‬\n\n\n                                                                                            ‫‪62‬‬\n\f     ‫املدعــى عليــه حصــول خــاف بينــه وبني املواطن املذكــور حول إيجارات‬\n     ‫محــات املدعــى عليــه أدى إلــى مشــادة كالميــة بينهمــا نتــج عنــه تلفــظ‬\n     ‫املدعــى عليــه باللفــظ الــوارد يف إجابتــه وهــو قولــه مــا يف حــل إال أنــي‬\n     ‫أحــط قفــل علــى قفلــك وال تقــدر تفتــح احملــل حتــى يســيل دمــي ودمــك يف‬\n     ‫الشــارع وهــذا اللفــظ الصــادر مــن املدعــى عليــه موافــق يف املعنــى للفــظ‬\n     ‫الــوارد يف دعــوى املدعــي العــام حيــث تضمــن تهديــد ًا للمذكــور بإقفــال‬\n     ‫احملــل وعــدم اســتطاعته لفتحــه حتــى حتصــل بينهمــا مقاتلــة تســيل علــى‬\n     ‫إثرهــا الدمــاء وســواء وصــل الــدم لألحســبة أم لــم يصــل فاملعنــى واحــد‬\n     ‫وهــذا يــدل علــى شــعور املدعــى عليــه بالغــن بســبب مماطلــة املذكــور‬\n     ‫يف دفــع إيجــارات محالتــه وقــد ثبــت يف الصحيحــن أن النبــي صلــى‬\n     ‫اهلل عليــه وســلم قــال ( إن لصاحــب احلــق مقــاالً) وحيــث ان مــا ورد يف‬\n     ‫شــهادة املدعــى عليــه يؤيــد أن منشــأ اخلــاف بــن املدعــى عليــه و‪ ......‬هــو‬\n     ‫إيجــار محــات املدعــى عليــه لذلــك كلــه ولكــون املدعــى عليــه معلــم‬\n     ‫وكبيــر يف الســن ولــم يظهــر لــي منــه أمــارات الطيــش واالســتخفاف‬\n     ‫بالدمــاء وإمنــا كان ذلــك منــه يف حلظــة غضــب يكثــر حصولــه بــن‬\n     ‫أربــاب احلقــوق لذلــك كلــه فقــد قــررت االكتفــاء بأخــذ التعهــد علــى‬\n     ‫املدعــى عليــه بعــدم التعــرض ل‪ ......‬بــأي نــوع مــن األذى يف نفســه أو مالــه‬\n     ‫أو عرضــه وإذا كان لــه عليــه مطالبــات فيتقــدم بذلــك بشــكوى تأخــذ‬\n     ‫مجراهــا الشــرعي والنظامــي وبــه حكمــت وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه قــرر قناعتــه باحلكــم وقــرر املدعــي العــام عــدم قناعتــه معتبــر ًا‬\n     ‫الئحــة الدعــوى الئحتــه االعتراضيــة وســيتم رفــع كامــل أوراق املعاملــة‬\n     ‫إلــى محكمــة االســتئناف كاملتبــع وأغلقــت اجللســة الســاعة ‪ 11‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪63‬‬\n\f                                                       ‫حــرر يف ‪1434/5/8‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة مبحافظــة بقلــوة برقــم ‪ 34262843‬وتاريــخ‬\n‫‪1434/6/7‬هـ املرفق بها القرار رقم ‪34220023‬وتاريخ‪1434/5/22‬هـ‬\n‫الصــادر مــن فضيلــة الشــيخ ‪ ....../‬القاضــي باحملكمــة العامــة مبحافظــة‬\n‫قلــوة املتضمــن دعــوى املدعــي العــام ضــد ‪ ....../‬ســعودي اجلنســية املتهــم‬\n‫يف تهديــد شــخص بالقتــل احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                  ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":58,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2418dd9e663cf948ee6d1fb9934535392c46aa530cfa95b623992b8ef586104e","normalized_text_hash":"c0d721369d83691c6c36cc07078df738fd4174e715160652c1501acc0d0c2056","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p58-3422002"},{"id":"d1e19043-fd7d-5961-9dec-672e1b2ca646","document_type":"judgment","category":"judicial","subcategory":"general","title":"تهديد -تهديد املدعى عليه ألسرته بإطاق النار على باب منزلهم بساح ناري -تضليل جهة التحقيق بإخفائه للساح الذي استخدمه -رجوع املقر عن إقراره ال يقبل إذا كان موجبه التعزير -التعزير بالسجن واجللد علن ا وأخذ التعهد -تشديد العقوبة للجرائم املنتشرة.","document_number":"33708489","case_number":"33708489","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وبرفقها القرار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/1/18","year":"1434","subject":"تهديد -تهديد املدعى عليه ألسرته بإطاق النار على باب منزلهم بساح ناري -تضليل جهة التحقيق بإخفائه للساح الذي استخدمه -رجوع املقر عن إقراره ال يقبل إذا كان موجبه التعزير -التعزير بالسجن واجللد علن ا وأخذ التعهد -تشديد العقوبة للجرائم املنتشرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33708489 :‬تاريخه‪1433/1/18 :‬ه‬\n                   ‫رقم الدعوى‪33708489:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34168360‬تاريخه‪1434/3/22 :‬هـ‬\n\n\n‫تهديــد ‪ -‬تهديــد املدعــى عليــه ألســرته بإطــاق النــار علــى بــاب منزلهــم‬\n‫بســاح نــاري ‪ -‬تضليــل جهــة التحقيــق بإخفائــه للســاح الــذي‬\n‫اســتخدمه ‪ -‬رجــوع املقــر عــن إقــراره ال ُيقبــل إذا كان موجبــه التعزيــر‬\n‫‪ -‬التعزيــر بالســجن واجللــد علن ـ ًا وأخــذ التعهــد ‪ -‬تشــديد العقوبــة‬\n                                                          ‫للجرائــم املنتشــرة‪.‬‬\n\n\n\n\n‫قــال ابــن قدامــة رحمــه اهلل(( وال يقبــل رجــوع املقــر عــن إقــراره إال فيمــا‬\n‫كان حــد ًا هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه فأمــا حقــوق‬\n‫اآلدميــن وحقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهات كالــزكاة‬\n‫والكفــارات فــا يقبــل رجوعــه عنــه وال نعلــم يف هــذا خالف ـ ًا)) املغنــي ‪،‬‬\n                                                                          ‫‪278/7‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بتهديــد أســرته بإطــاق النــار علــى بــاب‬\n‫منزلهــم بســاح نــاري وتضليــل جهــة التحقيــق بإخفائــه للســاح الــذي‬\n‫اســتخدمه‪ ،‬وذلــك بعــد ورود بــاغ للجهــات املختصــة عــن وجــود حالــة‬\n‫إطــاق نــار‪ ،‬وعنــد التوجــه إلــى املوقــع وجــد املب ِّلــغ وذكــر أن املدعــى‬\n‫عليــه قــام بإطــاق النــار علــى إخوتــه ولــم يصــب أحــد بــأذى وأثــر‬\n\n                                                                                       ‫‪72‬‬\n\f     ‫الرصــاص يف بــاب البيــت‪ ،‬وقــد أثبــت تقريــر فنــي األســلحة أنــه مبعاينــة‬\n     ‫املوقــع والفحــص الفنــي لــه‪ ،‬كان عبــارة عــن إطــاق نــار علــى بــاب‬\n     ‫منــزل ودخــول املقــذوف النــاري وارتطامــه باجلــدار ومت رفــع عــدد ظــرف‬\n     ‫فــارغ عيــار ‪ 7,65‬مــن عنــد بــاب املنــزل ومقــذوف نــاري عيــار ‪ 7,65‬مــن‬\n     ‫داخــل املنــزل‪ ،‬وقــد طلــب املدعــي العــام إثبــات مــا أســند إلــى املدعــى‬\n     ‫عليــه واحلكــم عليــه بعقوبــة تعزيريــة‪ ،‬بعــرض الدعــوى علــى املدعــى‬\n     ‫ا ولوجــود اقــرار حتقيق ـ ًا للمدعــى عليــه‬  ‫عليــه أنكرهــا جملــة وتفصي ـ ً‬\n     ‫مت االطــاع علــى التقريــر الفنــي لألســلحة وثبتــت إدانــة املدعــى عليــه‬\n     ‫مبــا جــاء يف دعــوى املدعــي العــام ومت احلكــم بتعزيــره بســجنه مــدة ســنة‬\n     ‫واحــدة وجلــده خمســن جلــدة علنـ ًا تكــرر عليــه ثــاث مــرات بــن كل‬\n     ‫مــرة وأخــرى مــدة ال تقــل عــن أســبوعني مــع أخــذ التعهــد الشــديد عليــه‬\n     ‫بعــدم العــودة ملثــل مــا بــدر منــه‪ ،‬وبعــرض احلكــم علــى املدعــى عليــه لــم‬\n     ‫يقنــع بــه وطلــب رفــع احلكــم حملكمــة االســتئناف كمــا قــرر املدعــي‬\n     ‫العــام عــدم اعتراضــه‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                    ‫املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بنجــران برقــم ‪ 33708489‬وتاريــخ ‪ 1433/12/27‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 332259319‬وتاريــخ ‪ 1433/12/27‬ه ـ ففــي‬\n     ‫يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت اجللســة الســاعة‪8:15‬‬\n     ‫بشــأن دعــوى املدعــي العــام ‪ ......‬واملكلــف مبهمــة اإلشــراف علــى‬\n\n‫‪73‬‬\n\f‫مكتــب االدعــاء العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس‬\n‫فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة جنــران رقــم ‪ ......‬وتاريــخ‬\n‫‪1430/12/29‬ه ـ ضــد ‪ ......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم ‪ ......‬قائــا يف دعــواه عليــه إنــه ورد مبحضــر تنفيــذ املهمــة رقــم‬\n‫(‪ (48198‬وتاريــخ ‪1433/11/27‬ه ـ املعــد مــن قبــل الدوريــات األمنيــة‬\n‫بنجــران أنــه وردهــم بــاغ مــن العمليــات عــن وجــود حالــة إطــاق نــار ومت‬\n‫التوجــه إلــى املوقــع ووجــد املبلــغ ‪ ...... /‬وذكــر بــأن املتهــم املذكــور قــام‬\n‫بإطــاق النــار علــى إخوتــه ولــم يصــب أحــد بــأذى وأثــر الرصــاص يف بــاب‬\n‫البيــت‪ .‬مت توقيــف املتهــم اســتنادا للمــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة‪ .‬وبســماع أقــوال املتهــم أفــاد بأنــه قــام بإطــاق النــار علــى‬\n‫إخوتــه باســتخدام مســدس حتفــظ علــى اســم صاحبــه (فــرزت اوراق‬\n‫للســاح وقيــدت برقــم ‪ ......‬وتاريــخ ‪ )1433/12/19‬وذلــك ألنــه كان‬\n‫متضايقـ ًا إلخبارهــم أبيــه عــن كل شــيء يفعلــه ‪.‬وباســتجواب املتهــم أقــر‬\n‫بأنــه أطلــق النــار يف الهــواء داخــل البيــت ألنــه كان غاضب ـ ًا علــى إثــر‬\n‫خــاف عائلــي وان الســاح املســتخدم مــن نــوع مســدس وانــه يعــود لــه‬\n‫وقــد اشــتراه مــن أحــد األشــخاص ال يعرفــه عنــد مــروره بإحــدى املــزارع‬\n‫قبــل عــدة ســنوات وأنــه رمــى الســاح يف الــوادي بعــد هروبــه مــن البيــت ‪.‬‬\n‫وقــد أثبــت تقريــر فنــي األســلحة رقــم (‪ ) ......‬وتاريــخ ‪1433/11/27‬ه ـ‬\n‫أنــه مبعاينــة املوقــع والفحــص الفنــي لــه كان عبــارة عــن إطــاق نــار‬\n‫علــى بــاب منــزل ودخــول املقــذوف النــاري وارتطامــه باجلــدار ومت رفــع‬\n‫عــدد ظــرف فــارغ عيــار ‪ 7,65‬مــن عنــد بــاب املنــزل ومقــذوف نــاري عيــار‬\n‫‪ 7,65‬مــن داخــل املنــزل‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام ل‪...... /‬‬\n‫بتهديــد أســرته بإطــاق النــار علــى بــاب منزلهــم بســاح نــاري وتضليــل‬\n\n\n                                                                                         ‫‪74‬‬\n\f     ‫جهــة التحقيــق بإخفائــه للســاح الــذي اســتخدمه‪.‬وذلك لألدلــة والقرائــن‬\n                                                                                 ‫التاليــة‪:‬‬\n     ‫‪ /1‬مــا جــاء يف اســتجواب املتهــم املنــوه عنهــا واملدونــة ص (‪ )2-1‬مــن‬\n                                                      ‫دفتــر التحقيــق لفــة رقــم (‪.)15‬‬\n     ‫‪ /2‬مــا جــاء يف ســماع أوقــال املتهــم املنــوه عنهــا واملدونــة ص(‪ )5‬مــن‬\n                                      ‫دفتــر تقريــر األحــوال األمنيــة لفــة رقــم (‪.)1‬‬\n           ‫‪ /3‬ما جاء يف محضر تنفيذ املهمة املنوه عنه واملرفق لفة رقم (‪.)3‬‬\n          ‫‪ /4‬ما جاء يف تقرير فني األسلحة املرفق صورة منه لفة رقم (‪. (26‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليــه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة تردعــه وتزجــر غيــره ‪( .‬علم ـ ًا بــأن احلــق‬\n     ‫اخلــاص مــازال قائم ـ ًا ) وبــاهلل التوفيــق هــذه دعــواي وبعــرض الدعــوى‬\n     ‫علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح‬\n     ‫ا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي العــام هــل‬      ‫جملــة وتفصيـ ً‬\n     ‫لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي بينــة ســوى مــا‬\n     ‫جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق واالطــاع علــى‬\n     ‫أقــوال املدعــى عليــه األوليــة املدونــة علــى ص ‪ 5‬مــن امللــف املرفــق علــى‬\n     ‫لفــة رقــم ‪ 1‬و علــى أقــوال املدعــى عليــه حتقيقــا املدونــة علــى ص ‪2,1‬‬\n     ‫مــن امللــف املرفــق علــى لفــة رقــم ‪ 15‬كمــا جــرى منــي االطــاع علــى‬\n     ‫تقريــر فنــي األســلحة رقــم ‪ 54‬وتاريــخ ‪1433/11/27‬ه ـ ثــم جــرى منــي‬\n     ‫ســؤال املدعــى عليــه عــن صحــة مــا جــاء يف أقوالــه األوليــة و أقوالــه‬\n     ‫حتقيق ـ ًا فقــال لقــد قمــت باإلمضــاء علــى أقوالــي األوليــة وأقوالــي لــدى‬\n     ‫جهــة التحقيــق ببصمــة إبهامــي ولــم أكــن أعــرف مــا هــو الــكالم الــذي‬\n\n\n‫‪75‬‬\n\f‫قمــت باإلمضــاء عليــه و أنــا أعــرف القــراءة والكتابــة هكــذا أجــاب‬\n‫ثــم جــرى منــي ســؤال املدعــى عليــه هــل اســتخدم معــك احملقــق وســيلة‬\n‫مــن وســائل اإلكــراه لكــي تعتــرف مبــا نســب إليــك فقــال لــم يســتخدم‬\n‫معــي احملقــق شــيئ ًا مــن ذلــك فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n‫وحيــث إن املدعــى عليــه قــد اعتــرف حتقيق ـ ًا بأنــه قــام بإطــاق طلقــة‬\n‫ناريــة مــن ســاح مســدس خــارج منــزل أهلــه يف الهــواء بســبب خــاف‬\n‫عائلــي وأنــه قــام برمــي الســاح يف الــوادي بعــد ذلــك وأنــه اشــترى‬\n‫الســاح مــن شــخص يتحفــظ عــن ذكــر اســمه ومبــا أن املدعــى عليــه‬\n‫قــد اعتــرف بأنــه قــام باإلمضــاء ببصمــة إبهامــه علــى أقوالــه حتقيق ـ ًا‬\n‫وأنــه يعــرف القــراءة والكتابــة وبــأن احملقــق لــم يســتعمل معــه إحــدى‬\n‫وســائل اإلكــراه وملــا كان رجــوع املقــر عــن إقــراره ال يقبــل إذا كان‬\n‫موجبــه التعزيــر قــال ابــن قدامــة رحمــه اهلل ‪ « :‬وال يقبــل رجــوع املقــر‬\n‫عــن إقــراره إال فيمــا كان حــد ًا هلل تعالــى يــدرأ بالشــبهات ويحتــاط‬\n‫إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال تــدرأ‬\n‫بالشــبهات كالــزكاة والكفــارات فــا يقبــل رجوعــه عنــه وال نعلــم‬\n‫يف هــذا خالفـ ًا « ( املغنــي ‪ )278/7 ،‬واســتناد ًا علــى مــا جــاء يف تقريــر‬\n‫فنــي األســلحة رقــم (‪ )54‬وتاريــخ ‪1433/11/27‬ه ـ املتضمــن بأنــه بعــد‬\n‫معاينــة املوقــع والفحــص الفنــي لــه تبــن بــأن احلــادث عبــارة عــن إطــاق‬\n‫نــار علــى بــاب منــزل ودخــول املقــذوف النــاري وارتطامــه باجلــدار ومت رفــع‬\n‫عــدد ظــرف فــارغ عيــار ‪ 7,65‬مــن عنــد بــاب املنــزل ومقــذوف نــاري عيــار‬\n‫‪ 7,65‬مــن داخــل املنــزل ونظــر ًا إلــى صغــر ســن املدعــى عليــه وألنــه ال‬\n‫يوجــد لديــه ســوابق جنائيــة وتأسيسـ ًا علــى جميــع مــا ســبق فقــد قــررت‬\n‫مــا يأتــي أوال‪ :‬ثبــت لــدي إدانــة املدعــى عليــه مبــا جــاء يف دعــوى املدعــي‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫العــام ثاني ـاً‪ :‬تعزيــره وذلــك بســجنه ملــدة ســنة واحــدة تبــدأ اعتبــارا مــن‬\n     ‫تاريــخ إدخالــه الســجن وجلــده خمســن جلــدة علن ـ ًا تكــرر عليــه ثــاث‬\n     ‫مــرات بــن كل مــرة وأخــرى مــدة ال تقــل عــن أســبوعني ثالث ـاً‪ :‬يؤخــذ‬\n     ‫التعهــد الشــديد عليــه بعــدم العــودة ملثــل مــا بــدر منــه هــذا مــا ظهــر لــي‬\n     ‫وبــه حكمــت ولــم يقنــع بــه املدعــى عليــه وطلــب رفــع احلكــم حملكمــة‬\n     ‫االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم نســخة احلكــم بعــد عشــرة‬\n     ‫أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن يومــا مــن التاريــخ احملــدد‬\n     ‫الســتالم نســخة احلكــم كمــا قــرر املدعــي العــام عــدم اعتراضــه وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                            ‫حــرر يف‪1434/1/11‬ه ـ الســاعة ‪.00:9‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/05/13‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 02:00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34168360‬وتاريــخ ‪1434/03/22‬ه ـ‬\n     ‫ونــص احلاجــة منــه ‪ (:‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n     ‫تقــررت إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي‪ :‬أو ًال ‪ /‬الســجن‬\n     ‫احملكــوم بــه علــى املدعــى عليــه كثيــر ثاني ـ ًا ‪ /‬يوجــد ســقط مشــار‬\n     ‫حتتــه بقلــم الرصــاص يف الصفحــة الثالثــة مــن القــرار الشــرعي فيضــاف‬\n     ‫وعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم ) وأجيــب مشــايخي‬\n     ‫أصحــاب الفضيلــة قضــاة محكمــة االســتئناف ســلمهم اهلل مبــا يأتــي ‪:‬‬\n     ‫أو ًال ‪ /‬فيمــا يخــص املالحظــة األولــى فأجيــب عنهــا بأنــي أرى مناســبة‬\n     ‫العقوبــة احملكــوم بهــا يف حــق املدعــى عليــه وذلــك النتشــار جرائــم‬\n     ‫إطــاق النــار يف اآلونــة األخيــرة ممــا يســتدعي معــه التشــديد يف عقوبــة‬\n     ‫مرتكبيهــا مبــا يحقــق الزجــر والــردع كما أن املدعــى عليه قام بإطالق‬\n\n\n‫‪77‬‬\n\f‫النــار علــى بــاب منــزل أســرته مــن أجــل تهديدهــم وأخفــى الســاح الــذي‬\n‫أطلــق منــه النــار ثاني ـ ًا ‪ /‬فيمــا يخــص املالحظــة الثانيــة فأجيــب عنهــا‬\n‫بأنــه قــد جــرى إكمــال الــازم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بنجــران برقم ‪34836784‬‬\n‫وتاريــخ ‪1434 /6/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...... /‬برقــم ‪ 3414679‬وتاريــخ ‪1434/1/18‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ض ــد ‪ ...... /‬يف قضيــة ( تهديــد الغيــر)‬\n‫علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n‫ـاء علــى قرارنــا رقــم ( ‪ ) 34168360‬وتاريــخ ‪1434/3/22‬ه ـ‬          ‫ضبطــه بنـ ً‬\n‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪78‬‬\n\f79\n\f80\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":72,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"efdd83861f07fd28b0192d3a52093e4b97113996ac7273d5bed95f5ec675b5cf","normalized_text_hash":"32c60ad4f610d6bbbd715eb1114e95fb179ff10dfa4ed56cc3787d14f870797d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p72-33708489"},{"id":"4f9fd410-636e-5fd8-b46f-c40fb88a08ba","document_type":"judgment","category":"judicial","subcategory":"general","title":"جرائم معلوماتية -تدمير مواقع الكترونية -تدمير موقع صحيفة الكترونية -التعزير لقوة االتهام بناء على تقرير أهل اخلبرة - التعزير بالسجن ومصادرة أداة اجلرمية.","document_number":"3465258","case_number":"3426314","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/17","year":"1434","subject":"جرائم معلوماتية -تدمير مواقع الكترونية -تدمير موقع صحيفة الكترونية -التعزير لقوة االتهام بناء على تقرير أهل اخلبرة - التعزير بالسجن ومصادرة أداة اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪3465258 :‬تاريخه‪1434/3/17 :‬هـ‬\n                         ‫رقم الدعوى‪3426314:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 35110953‬تاريخه‪1435/01/10:‬هـ‬\n\n\n     ‫جرائــم معلوماتيــة ‪ -‬تدميــر مواقــع الكترونيــة ‪ -‬تدميــر موقــع صحيفــة‬\n     ‫الكترونيــة ‪-‬التعزيــر لقــوة االتهــام بنــاء علــى تقريــر أهــل اخلبــرة ‪-‬‬\n                                  ‫التعزيــر بالســجن ومصــادرة أداة اجلرميــة‪.‬‬\n\n\n\n\n                       ‫‪ -‬املادة (‪ )3/13‬من نظام مكافحة اجلرائم املعلوماتية‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن قبــل املدعــي العــام علــى املدعــى عليهمــا‬\n     ‫بالدخــول غيــر املشــروع ألحــد املواقــع اإللكترونيــة وتغييــر بياناتــه‬\n     ‫اخلاصةوإتالفــه وطلــب إثبــات مــا أســند إليهمــا واحلكم عليهمــا بالعقوبة‬\n     ‫املنصــوص عليهابالفقــرة (‪ )3‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة اجلرائــم‬\n     ‫املعلوماتيــة ومصــادرة جهــاز احلاســب اآللــي العائــد للمدعــى عليــه األول‬\n     ‫وجهــاز احلاســب اآللــي العائــد للمدعــى عليــه الثانــي املســتخدمة يف‬\n     ‫اجلرميــة وفق ـ ًا للمــادة (‪)13‬مــن ذات النظــام ‪ -‬حيــث تعــرض أحــد مواقــع‬\n     ‫الصحــف االلكترونيــة لالختــراق والتدميــر وتغييــر التصميــم لصــور‬\n     ‫فاضحــة وقــد أنكــر املدعــى عليــه األول التهمــة ودفــع بــأن جــاره املدعــى‬\n     ‫عليــه الثانــي يشــترك معــه يف اســتعمال الرقــم ‪ -‬أنكــر املدعــى عليهمــا‬\n     ‫الدعــوى والتهــم املوجهــة إليهمــا ‪ -‬أقــر املدعــى عليــه األول بــأن رقــم اآلي‬\n\n‫‪81‬‬\n\f‫بــي املشــار لــه يف الئحــة الدعــوى يعــود لــه إال أنــه دفــع بأنــه يشــترك معــه‬\n‫جــاره اآلخــر يف املعالــج ‪ -‬أقــر املدعــى عليــه الثاني بأنه يشــترك مع األول‬\n‫يف املعالــج ‪ -‬بنــاء علــى التقريــر املعــد مــن قبــل املجموعــة املتخصصــة‬\n‫لتقــدمي اخلدمــات االلكترونيــة للشــبكة العنكبوتيــة وبنــاء علــى إفــادة‬\n‫اجلهــة األمنيــة املتضمنــان صــدور هــذا الفعــل مــن رقــم املدعــى عليــه األول‬\n‫وإقــرار املدعــى عليــه األول بــأن الرقــم يعــود لــه وإلقــرار املدعــى عليــه‬\n‫الثانــي باشــتراكه مــع األول يف الرقــم فقــد حكمــت احملكمــة علــى‬\n‫املدعــى عليــه األول بســجنه ســتة أشــهر واملدعــى عليــه الثانــي بأربعــة‬\n‫أشــهر ‪ -‬قــرر املدعــى عليهمــا قناعتهمــا باحلكــم بينمــا اعتــرض املدعــي‬\n‫العــام مكتفيــا بــأوراق املعاملــة بــدون تقــدمي الئحــة ‪-‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬املــازم القضائــي يف احملكمــة‬\n‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                           ‫ّ‬\n‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 3426314‬وتاريــخ‬\n‫‪1434/1/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34128105‬وتاريــخ‬\n‫‪ 1434/01/17‬ه ـ وبنــاء علــى تعميــدي مــن قبــل القاضــي ‪...........‬‬\n‫باخلطــاب رقــم ‪ 331633101‬يف ‪1433/8/17‬ه ـ ففــي هــذا اليوم األحد‬\n‫املوافق‪ 1434/03/15‬هـ افتتحت اجللسة الساعة ‪ 08 : 15‬وفيها حضر‬\n‫املدعــي العــام ‪...........‬وادعــى علــى احلاضريــن معــه كال مــن ‪...........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪...........‬واملدعــو‪ ...........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪...........‬قائــا يف دعــواه انــه باالطــاع علــى خطــاب رئيــس‬\n\n                                                                                          ‫‪82‬‬\n\f     ‫حتريــر صحيفــة ‪...........‬االلكترونيــة بشــأن انــه بتاريــخ ‪1432/7/17‬ه ـ‬\n     ‫تعــرض موقعهــم للتخريــب وتغييــر التصميــم الــى صــور نســائية فاضحــه‬\n     ‫وإتــاف املوقع‪.‬وباالطــاع علــى التقريــر املعــد مــن قبــل مجموعــة ‪...........‬‬\n     ‫خلدمــات الويــب اتضــح ان رقــم االي بــي ملختــرق الصحيفــة هــو (‪)...........‬‬\n     ‫وبضبــط جهــاز حاســب الــى (مكتبــي لونــه اســود ) عائــد للمدعــى عليــه‬\n     ‫األول ‪ ،‬كمــا ضبــط جهــاز حاســب آلــي (مكتبــي لونــه رصاصــي) عائــد‬\n     ‫للمدعــى عليــه الثاني‪.‬وباالطــاع علــى خطــاب ســعادة مســاعد مديــر‬\n     ‫االمــن العــام لشــئون األمــن ‪...........‬يف ‪1433/3/23‬ه ـ واملتضمــن انــه مت‬\n     ‫إخضــاع امللقــم ‪ ...........‬للمعاجلــه الفنيــة وتبــن انــه اســتخدم بالدخــول‬\n     ‫علــى شــبكة االنترنــت مــن خــال الهاتــف رقــم‪ ...........‬املســجل باســم‬\n     ‫املواطــن‪....................... /‬وباســتجواب املدعــى عليــه األول ‪ /‬أنكــر‬\n     ‫قيامــه باختــراق املوقــع التابــع لصحيفــة ‪...........‬االلكترونيــة واقــر أن‬\n     ‫رقــم الهاتــف واالي بــي عائــد لــه وأفــاد أن هنــاك شــخص آخــر مشــترك‬\n     ‫معــه يف نفــس املــودم يدعــى ‪........... /‬منــذ شــهر رجــب مــن عــام ‪1432‬هــ‪.‬‬\n     ‫وباســتجواب املدعــى عليــه الثانــي ‪ /‬أنكــر قيامــه باختــراق املوقــع التابــع‬\n     ‫لصحيفــة ‪...........‬االلكترونيــة واقــر انــه مشــترك مــع جــاره املدعــى عليه‬\n     ‫األول باســتخدام شــبكة االنترنــت مــن شــهر رجــب مــن عــام ‪1432‬هــ‪.‬‬\n     ‫ومبواجهــة املدعــى عليــه االول بالثانــي‪ /‬أصــر كال منهــم علــى أقوالــه‪.‬‬\n     ‫وقد أســفر التحقيق عن توجيه االتهام لهما بالدخول غير املشــروع إلى‬\n     ‫موقــع الكترونــي وتغييــر بياناتــه اخلاصــة ومعاجلــة وإتالفــه وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة ‪ -1 -:‬إقرارهــم املنــوه عنــه املــدون علــى الصفحــات‬\n     ‫رقــم (‪ )6/1‬مــن دفتــر التحقيــق لفــه رقــم(‪ )22‬والصفحــات رقــم (‪)2-1‬‬\n     ‫مــن دفتــر التحقيــق املرفــق لفــه رقــم (‪-2) 56‬محضــر املواجهــة املنــوه‬\n\n\n‫‪83‬‬\n\f‫عنــه املــدون علــى الصفحــة رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه‬\n‫رقــم (‪ -3 )56‬التقريــر املعــد مــن قبــل مجموعــه ‪...........‬خلدمــات الويــب‬\n‫املرفــق علــى اللفــة رقــم (‪-4 )3‬خطــاب ســعادة مســاعد مديــر األمــن‬\n‫العــام لشــئون األمــن املرفــق علــى اللفــة رقــم (‪ )7‬وبالبحــث عمــا إذا كان‬\n‫لهمــا ســوابق لــم يعثــر لهمــا علــى ســوابق مســجلة حتــى تاريخــه وحيــث إن‬\n‫مــا أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرعا فعــل‬\n‫محــرم ومعاقــب عليــه نظامـ ًا وفقـ ًا لنظــام مكافحــة جرائــم املعلوماتيــة‬\n‫اطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بالعقوبــة املنصــوص‬\n‫عليهــا بالفقــرة (‪ )3‬مــن املــادة (‪ )3‬مـ ــن النظــام املشــار إليــه ومصــادرة‬\n‫جهــازه احلاســب االلــي (مكتبــي لونــه اســود) عائــد للمدعــى عليــه االول‬\n‫وجهــاز احلاســب االلــي ( مكتبــي لونــه رصاصــي) العائــد للمدعــى عليــه‬\n‫الثانــي املســتخدمة يف اجلرميــة وفق ـ ًا للمــادة (‪ )13‬مــن ذات النظــام علم ـ ًا‬\n‫أن احلــق اخلــاص مــازال قائمــا‪ .‬هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n‫ا جميــع مــا‬ ‫علــى املدعــى عليهمــا أجــاب كل واحــد منهمــا مبفــرده قائـ ً‬\n‫ذكــره املدعــي العــام يف دعــواه مــن اختــراق موقــع ‪...........‬لألكترونيات‬\n‫فغيــر صحيــح هكــذا أجابــا وبســؤال املدعــي العــام هــل لديــه بينــة‬\n‫علــى ذلــك قــال ليــس لــدي بينــة ســوى مــا يف أوراق املعاملــة كمــا جــرى‬\n‫الرجــوع إلــى أوراق املعاملــة فلــم أجــد إقــرار املدعــى عليهمــا بإختــراق‬\n‫املوقــع املذكــور يف الدعــوى كمــا جــرى الرجــوع إلــى التقريــر املعــد‬\n‫مــن قبــل مجموعــة خلدمــات الويــب املرفــق علــى لفــة رقــم ‪ 3‬واملتضمــن‬\n‫اختــراق موقــع ‪.............‬لإللكترونيــات واملختــرق ورقــم أي بــي ‪...........‬‬\n‫أنتهــى كمــا جــرى الرجــوع إلــى خطــاب ســعادة مســاعد املديــر العــام‬\n‫لشــؤون األمــن واملرفــق علــى لفــة ‪ 7‬واملتضمــن إخضــاع امللقــم رقــم أي‬\n\n\n                                                                                      ‫‪84‬‬\n\f     ‫بــي ‪...........‬للمعاجلــة الفنيــة وتبــن أنــه اســتخدم بالدخــول علــى شــبكة‬\n     ‫االنترنــت بالهاتــف رقــم ‪...........‬واملســجل باســم املواطــن ‪...........‬وبعــرض‬\n     ‫ذلــك عليهــم أجــاب املدعــى عليــه األول أن رقــم أي بــي صحيــح وهــو‬\n     ‫يعــود لــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثانــي أننــي كنــت‬\n     ‫مشــترك مــع املدعــى عليــه األول بنفــس رقــم أي بــي فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى عليــه األول ‪...........‬بــأن‬\n     ‫رقــم األي بــي عائــد لــه وإقــرار املدعــى عليــه الثانــي ‪ ...........‬اننــي كنــت‬\n     ‫مشــترك مــع املدعــى عليــه األول بنفــس رقــم االي بــي وبنــاء علــى ذلــك‬\n     ‫كلــه ولقــوة االتهــام فقــد حكمــت علــى املدعــى عليــه األول ‪...........‬‬\n     ‫بســجنه ملــدة ســتة أشــهر واملدعــى عليــه الثانــي ‪...........‬بســجنه ملــدة أربعــة‬\n     ‫أشــهر وبعــرض ذلــك عليهمــا قــررا القناعــة بــه بينمــا قــرر املدعــي العــام‬\n     ‫عــدم قناعتــه وطلــب االســتئناف فأجبتــه لطلبــه وقــرر بأنــه لــن يقــدم‬\n     ‫الئحــة اعتراضيــة وإمنــا يكتفــي بــأوراق املعاملــة والئحــة الدعــوى عــن‬\n     ‫االعتــراض واهلل املوفــق اثبتــه وللبيــان حــرر يف ‪1434/03/15‬ه ـ احلمــد‬\n     ‫هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة األولــى‬\n     ‫مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف برقــم‬\n     ‫‪ 342572130‬وتاريــخ ‪1434/11/27‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34/2764425‬وتاريــخ ‪1434/12/3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪...........‬املســجل برقــم‬\n     ‫‪ 3465258‬وتاريــخ ‪1434/3/17‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام‬\n     ‫ضــد‪........... -...................... -1/‬يف قضيــة تدميــر موقــع الكترونــي‬\n     ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n\n\n‫‪85‬‬\n\f‫حيــث ســبق دراســة القراروصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه‬\n‫بنــاء علــى قرارنــا رقــم‪ 34212756‬يف‪1434/5/14‬ه ـ قررنــا املصادقــة‬\n‫علــى احلكــم وذلــك النتقــال فضيلــة ناظــر القضيــة مــن احملكمــة ولئــا‬\n‫تتأخــر القضيــة ويطــول امــد نظــر القضيــة واهلل املوفــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1435/1/8‬ه ـ‬\n\n\n\n\n                                                                                 ‫‪86‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":81,"source_page_end":86,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bd875852167bb9ea38152d59fa4108f818515ad0090f5790bd1f1b5a6b292a14","normalized_text_hash":"919b26e88d29f2be4c3e11cf7e5e4dcdcafff85f6daa847f98ffed74de0f7bab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p81-3465258"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

